"A pay change is a new record from its effective date; the previous record ends the day before. Leave the funding amounts blank to use the guideline calculation":"वेतन में बदलाव उसकी प्रभावी तिथि से नया रिकॉर्ड होता है; पिछला रिकॉर्ड एक दिन पहले समाप्त होता है। दिशानिर्देश की गणना उपयोग करने के लिए फंडिंग राशियाँ खाली छोड़ें",
