"A photo is added only when the dish clearly matches one in the food library. Staff can always change or remove it":"फ़ोटो तभी जोड़ी जाती है जब व्यंजन खाद्य लाइब्रेरी की किसी फ़ोटो से साफ़ मेल खाता हो। स्टाफ़ उसे कभी भी बदल या हटा सकता है",
