"A provider's bio goes in every new family's welcome email and on their provider card in the parents' app. Providers without one are reminded why it matters and given a link straight to":"प्रदाता का परिचय हर नए परिवार के स्वागत ईमेल में और अभिभावकों के ऐप में उनके प्रदाता कार्ड पर जाता है। जिन प्रदाताओं के पास यह नहीं है उन्हें याद दिलाया जाता है कि यह क्यों मायने रखता है और सीधे इसका लिंक दिया जाता है",
