"Added as a line on the invoice when a payment by that method is recorded or confirmed, split out of the amount received. Card surcharges in Canada are capped at 2.4% and not allowed on debit":"उस विधि से भुगतान दर्ज या पुष्ट होने पर चालान पर एक पंक्ति के रूप में जोड़ा जाता है, प्राप्त राशि में से अलग करके। कनाडा में कार्ड अधिभार 2.4% तक सीमित हैं और डेबिट पर अनुमत नहीं हैं",
"Added as a line when you next run payroll for them, and marked paid then":"अगली बार उनका वेतन चलाने पर एक पंक्ति के रूप में जुड़ जाता है और तभी भुगतान किया हुआ चिह्नित होता है",
