"Added to an agency's invoice when it is raised: every invoice, or just the next one. For a one-off on an invoice already raised, use Lines & payments on that invoice":"एजेंसी का चालान बनते समय उसमें जोड़ी जाती हैं: हर चालान में, या केवल अगले में। पहले से बने चालान पर एक बार के लिए, उस चालान की पंक्तियाँ और भुगतान का उपयोग करें",
