"Adds Wage Enhancement Grant and workforce compensation to payroll runs as separate pay-stub lines, tracks the 32-day rule and produces the year-end reconciliation. Rates per person are in":"पे-रन में वेज एन्हांसमेंट ग्रांट और कार्यबल मुआवज़े को अलग पे-स्टब लाइनों के रूप में जोड़ता है, 32-दिन के नियम को ट्रैक करता है और वर्ष-अंत मिलान तैयार करता है। प्रति व्यक्ति दरें यहाँ हैं:",
"Adds each public holiday to every centre’s calendar as a closure, so the schedule, autofill and attendance all treat it as a day off. A date you have already entered yourself is never overwritten":"हर सार्वजनिक छुट्टी को हर केंद्र के कैलेंडर में बंदी के रूप में जोड़ता है, ताकि शेड्यूल, ऑटोफ़िल और उपस्थिति इसे अवकाश मानें। जो तारीख़ आपने खुद दर्ज की है वह कभी नहीं बदली जाती",
"Adds the policies Ontario licensing asks for, as titles only":"ओंटारियो लाइसेंसिंग द्वारा माँगी गई नीतियाँ केवल शीर्षकों के रूप में जोड़ता है",
"Adds the policies Ontario licensing asks for, as titles only — you add your own text":"ओंटारियो लाइसेंसिंग द्वारा माँगी गई नीतियाँ केवल शीर्षकों के रूप में जोड़ता है — अपना टेक्स्ट आप जोड़ें",
"Adds “Pay by credit or debit card in the app” to the How to pay section of invoices and invoice emails. It only appears once your card payments are live. Interac e-Transfer shows whenever an address is set above":"चालान और चालान ईमेल के «भुगतान कैसे करें» अनुभाग में «ऐप में क्रेडिट या डेबिट कार्ड से भुगतान करें» जोड़ता है। यह तभी दिखता है जब आपके कार्ड भुगतान चालू हों। ऊपर पता सेट होने पर Interac e-Transfer हमेशा दिखता है",
