"Administration → Children lists every child across all your centres. Filter by centre/status, open a child for the full record: enrollment history, daily reports, live feed, attachments, and the emergency card":"प्रशासन → बच्चे में आपके सभी केंद्रों के हर बच्चे की सूची है। केंद्र/स्थिति से फ़िल्टर करें, पूरे रिकॉर्ड के लिए कोई बच्चा खोलें: नामांकन इतिहास, दैनिक रिपोर्ट, लाइव फ़ीड, अटैचमेंट और आपातकालीन कार्ड",
"Administration → Families. Add families and invite guardians by email":"प्रशासन → परिवार। परिवार जोड़ें और अभिभावकों को ईमेल से आमंत्रित करें",
"Administration → Families. Add families and invite guardians by email — they get a parent-portal login to see their child's day, photos, and invoices":"प्रशासन → परिवार। परिवार जोड़ें और अभिभावकों को ईमेल से आमंत्रित करें — उन्हें अभिभावक पोर्टल का लॉग इन मिलता है जिससे वे अपने बच्चे का दिन, फ़ोटो और चालान देख सकें",
"Administrator":"प्रशासक",
"Admins and directors get one email listing the completed forms still waiting for their review and counter-signature. Only forms set to":"एडमिन और निदेशकों को एक ईमेल मिलता है जिसमें वे पूर्ण फ़ॉर्म सूचीबद्ध होते हैं जो अब भी उनकी समीक्षा और प्रति-हस्ताक्षर की प्रतीक्षा में हैं। केवल वे फ़ॉर्म गिने जाते हैं जिन्हें इस पर सेट किया गया है",
