"Charged on the amount being paid, not on the invoice total — a family paying in two instalments is charged the fee on each, which is what the processor bills. Cash and cheque are never surcharged. Set 0 to absorb the cost yourself. The fee is added as a visible line on the invoice, and whoever records the payment confirms it first":"भुगतान की जा रही राशि पर लगता है, चालान के कुल पर नहीं — दो किस्तों में भुगतान करने वाले परिवार से हर किस्त पर शुल्क लिया जाता है, जो प्रोसेसर बिल करता है। नकद और चेक पर कभी अधिभार नहीं लगता। लागत खुद वहन करने के लिए 0 रखें। शुल्क चालान पर एक दिखने वाली पंक्ति के रूप में जुड़ता है, और भुगतान दर्ज करने वाला व्यक्ति पहले उसकी पुष्टि करता है",
