"Configure what each role can do in your agency. System roles (agency_admin, centre_director, etc.) can have their permissions tuned but not renamed or deleted. Create custom roles to model your real-world staff structure — e.g. Lead Educator, Floater, Centre Manager. Phase A: these permissions are recorded but not yet enforced; the v22p8 Phase B rollout will switch existing role checks to consult this matrix":"अपनी एजेंसी में तय करें कि हर भूमिका क्या कर सकती है। सिस्टम भूमिकाओं (agency_admin, centre_director आदि) की अनुमतियाँ बदली जा सकती हैं, लेकिन उनका नाम नहीं बदला जा सकता और न ही उन्हें हटाया जा सकता है। अपने स्टाफ़ के वास्तविक ढाँचे के अनुसार कस्टम भूमिकाएँ बनाएँ — जैसे मुख्य शिक्षक, फ़्लोटर, केंद्र प्रबंधक। चरण A: ये अनुमतियाँ दर्ज होती हैं लेकिन अभी लागू नहीं हैं; v22p8 चरण B रोलआउट मौजूदा भूमिका जाँचों को इस मैट्रिक्स से मिलान कराएगा",
