"Credit and debit cards, refunds and voids. One API token does everything":"क्रेडिट और डेबिट कार्ड, रिफ़ंड और वॉइड। एक ही API टोकन सब कुछ करता है",
"Credit and debit cards, refunds and voids. One API token does everything — create it in Helcim under All Tools → Integrations → API Access, with the Payment API permissions enabled. Cards are entered inside Helcim’s own window, so a card number never reaches KiddieTrac":"क्रेडिट और डेबिट कार्ड, रिफ़ंड और वॉइड। एक ही API टोकन सब कुछ करता है — इसे Helcim में All Tools → Integrations → API Access के अंतर्गत बनाएँ, Payment API अनुमतियाँ चालू रखकर। कार्ड Helcim की अपनी विंडो में दर्ज होते हैं, इसलिए कार्ड नंबर कभी KiddieTrac तक नहीं पहुँचता",
