"Earned is what each issued payslip or invoice is worth; paid is when your agency marked it paid. Voided documents are shown but never counted":"अर्जित वह है जो हर जारी पे-स्लिप या चालान का मूल्य है; भुगतान तब है जब आपकी एजेंसी ने उसे भुगतान किया हुआ चिह्नित किया। रद्द किए गए दस्तावेज़ दिखाए जाते हैं लेकिन कभी गिने नहीं जाते",
