"Editing — everything is open: Details, Allergies & health and every other tab. Each section saves with its own button; close the record when you are finished":"संपादन — सब कुछ खुला है: विवरण, एलर्जी और स्वास्थ्य और बाकी हर टैब। हर अनुभाग अपने बटन से सहेजा जाता है; काम पूरा होने पर रिकॉर्ड बंद करें",
"Editing — you can add children, guardians and contacts, set kiosk PINs, and remove guardians. Press Done when you have finished":"संपादन — आप बच्चे, अभिभावक और संपर्क जोड़ सकते हैं, कियोस्क PIN सेट कर सकते हैं और अभिभावकों को हटा सकते हैं। पूरा होने पर पूर्ण दबाएँ",
