"Educator (A-Z":"शिक्षक (A-Z",
"Educator (tablet view":"शिक्षक (टैबलेट व्यू",
"Educator award history":"शिक्षक पुरस्कार इतिहास",
"Educator award settings":"शिक्षक पुरस्कार सेटिंग्स",
"Educator awards":"शिक्षक पुरस्कार",
"Educator forgot to sign the child in":"शिक्षक बच्चे को साइन इन करना भूल गया",
