"Educator points are turned off for this agency":"इस एजेंसी के लिए शिक्षक पॉइंट बंद हैं",
"Educator sees it":"शिक्षक इसे देखता है",
"Educator-to-child ratio is within CCEYA standards. You have appropriate staffing for the children present":"शिक्षक-बच्चा अनुपात CCEYA मानकों के भीतर है। उपस्थित बच्चों के लिए आपके पास उचित स्टाफ है",
"Educators & providers":"शिक्षक और प्रदाता",
"Educators and other staff who forget to clock out. Affects timesheets and payroll":"शिक्षक और अन्य स्टाफ़ जो क्लॉक आउट करना भूल जाते हैं। टाइमशीट और पेरोल प्रभावित होते हैं",
"Educators are paid from their recorded hours":"शिक्षकों को उनके दर्ज घंटों के आधार पर भुगतान होता है",
"Educators sign & submit for their director/admin to review, sign and send to the family":"शिक्षक हस्ताक्षर कर जमा करते हैं ताकि उनके निदेशक/एडमिन समीक्षा करें, हस्ताक्षर करें और परिवार को भेजें",
