"Eligible: under 6. A child who turns 6 between January 1 and June 30 stays eligible until June 30 (preschool, kindergarten or family age group); otherwise until the end of the month they turn 6. In a school-age room, until the end of their birth month. A child whose enrolment is marked not CWELCC-eligible is counted as not eligible":"पात्र: 6 वर्ष से कम। जो बच्चा 1 जनवरी से 30 जून के बीच 6 साल का होता है, वह 30 जून तक पात्र रहता है (प्रीस्कूल, किंडरगार्टन या पारिवारिक आयु-समूह); अन्यथा 6 साल का होने वाले महीने के अंत तक। स्कूल-आयु कक्ष में, उसके जन्म-माह के अंत तक। जिस बच्चे का नामांकन CWELCC के लिए अपात्र चिह्नित है, उसे अपात्र गिना जाता है",
