"Every enrolled child across your centres. Change the status filter to include withdrawn or waitlisted children":"आपके केंद्रों में नामांकित हर बच्चा। वापस लिए गए या प्रतीक्षा सूची वाले बच्चों को शामिल करने के लिए स्थिति फ़िल्टर बदलें",
