"Every line takes its catalogue price (or the price you set with Price) and renews from its end date. Billing raises the invoices":"हर पंक्ति अपनी कैटलॉग कीमत (या कीमत से आपके तय की गई कीमत) लेती है और अपनी समाप्ति तिथि से नवीनीकृत होती है। बिलिंग चालान बनाती है",
