"For v22p1, the director records this on behalf of the parent. v22p2 will add the parent-side e-signature flow":"v22p1 के लिए, निदेशक यह अभिभावक की ओर से दर्ज करते हैं। v22p2 में अभिभावक की ओर से ई-हस्ताक्षर की सुविधा जुड़ेगी",
