"Off by default. When on, records past their retention period are handled automatically by a nightly review. Deletion is permanent":"डिफ़ॉल्ट रूप से बंद। चालू होने पर, अवधि पूरी कर चुके रिकॉर्ड रात्रिकालीन समीक्षा द्वारा अपने आप संभाले जाते हैं। हटाना स्थायी है",
"Off by default. When on, records past their retention period are handled automatically by a nightly review. Deletion is permanent — anonymising keeps aggregate stats while removing identifying details":"डिफ़ॉल्ट रूप से बंद। चालू होने पर, अवधि पूरी कर चुके रिकॉर्ड रात्रिकालीन समीक्षा द्वारा अपने आप संभाले जाते हैं। हटाना स्थायी है — गुमनाम करने पर पहचान वाले ब्योरे हट जाते हैं और कुल आँकड़े बने रहते हैं",
"Off by default: many email apps open messages on their own, so an open alone is not a reply":"डिफ़ॉल्ट रूप से बंद: कई ईमेल ऐप संदेश अपने आप खोल देते हैं, इसलिए केवल ओपन होना जवाब नहीं है",
"Off for the agency":"एजेंसी के लिए बंद",
"Off holds back every email to its educators and to the parents of its children":"बंद होने पर इसके शिक्षकों और इसके बच्चों के अभिभावकों को जाने वाले सभी ईमेल रोक दिए जाते हैं",
"Off holds back every email to its educators and to the parents of its children — useful while setting one up. Rooms follow their centre: a room cannot send while this is off. The full switchboard, including rooms, is under Settings → Email settings":"बंद होने पर इसके शिक्षकों और इसके बच्चों के अभिभावकों को जाने वाले सभी ईमेल रोक दिए जाते हैं — किसी को सेट करते समय उपयोगी। कक्ष अपने केंद्र का अनुसरण करते हैं: बंद होने पर कक्ष नहीं भेज सकता। कक्षों सहित पूरा स्विचबोर्ड सेटिंग्स → ईमेल सेटिंग्स में है",
"Off means no emails or bell notifications about bios":"बंद का मतलब है परिचय के बारे में कोई ईमेल या घंटी सूचना नहीं",
"Off means no payment can be taken or sent through this provider, whatever is stored below":"बंद का मतलब है कि इस प्रदाता के माध्यम से कोई भुगतान लिया या भेजा नहीं जा सकता, चाहे नीचे कुछ भी सहेजा हो",
"Off means no reminders. People are still told when a request is first made":"बंद होने पर कोई रिमाइंडर नहीं। अनुरोध किए जाने पर लोगों को फिर भी सूचित किया जाता है",
"Off means no reminders. The \"Form submitted\" notice still goes out when a form is signed":"बंद का मतलब है कोई अनुस्मारक नहीं। फ़ॉर्म साइन होने पर “फ़ॉर्म जमा किया गया” सूचना फिर भी जाती है",
"Off means only settled leave is shown. On is useful when planning cover":"बंद होने पर केवल तय हो चुकी छुट्टियाँ दिखती हैं। चालू होने पर स्थानापन्न की योजना बनाने में उपयोगी",
"Off means the overview card reads “Not set” rather than guessing":"बंद होने पर ओवरव्यू कार्ड अनुमान लगाने के बजाय “सेट नहीं” दिखाता है",
"Off removes the 👋 button for everyone at the agency":"बंद करने पर एजेंसी में सभी के लिए 👋 बटन हट जाता है",
"Off removes the 📞 button for everyone at the agency":"बंद करने पर एजेंसी में सभी के लिए 📞 बटन हट जाता है",
"Off until you turn it on. Saving credentials on its own never starts phones ringing":"जब तक आप चालू न करें, बंद रहता है। केवल क्रेडेंशियल सहेजने से कभी फ़ोन नहीं बजते",
"Off-board":"ऑफ़-बोर्ड करें",
