"Only do this if they told you so. It is stored against your name as the person who recorded it, with the date and the wording they were read":"ऐसा तभी करें जब उन्होंने आपसे यह कहा हो। यह आपके नाम से दर्ज करने वाले व्यक्ति के रूप में, तारीख और उन्हें पढ़कर सुनाए गए शब्दों के साथ सहेजा जाता है",
"Only do this when the person has asked to receive event invitations again":"यह तभी करें जब व्यक्ति ने कार्यक्रम आमंत्रण फिर से पाने के लिए कहा हो",
"Only educators who worked that day, on days the centre is open":"केवल उस दिन काम करने वाले शिक्षक, उन दिनों में जब केंद्र खुला हो",
"Only ever engages when the other carrier is fully set up, and only on a refusal":"यह तभी चलता है जब दूसरा कैरियर पूरी तरह सेट हो, और केवल मना किए जाने पर",
"Only ever engages when the other carrier is fully set up, and only on a refusal — a message already accepted is never sent twice":"यह तभी चलता है जब दूसरा कैरियर पूरी तरह सेट हो, और केवल मना किए जाने पर — पहले से स्वीकार किया गया संदेश कभी दो बार नहीं भेजा जाता",
"Only for invoices that charge tax; such invoices wait until one is chosen":"केवल उन चालानों के लिए जिनमें कर लगता है; ऐसे चालान दर चुने जाने तक रुके रहते हैं",
"Only forms signed at least":"केवल वे फ़ॉर्म जो कम से कम इतने समय पहले साइन हुए",
"Only happens once no child is enrolled here":"तभी होगा जब यहाँ कोई बच्चा नामांकित न रहे",
"Only if no push notification reaches them":"केवल तभी जब कोई पुश नोटिफ़िकेशन उन तक न पहुँचे",
"Only if the family has already given you one":"केवल तब जब परिवार ने आपको पहले ही दिया हो",
"Only if the family has already given you one — a photo or PDF of the record. You can add it later from the child’s record":"केवल तब जब परिवार ने आपको पहले ही दिया हो — रिकॉर्ड की फ़ोटो या PDF। आप इसे बाद में बच्चे के रिकॉर्ड से जोड़ सकते हैं",
"Only invoices issued on or after":"केवल इस तारीख को या उसके बाद जारी चालान",
"Only invoices settled in full":"केवल वे चालान जो पूरी तरह चुकाए गए हैं",
"Only invoices with money still owing":"केवल वे चालान जिनमें अभी भी पैसा बकाया है",
"Only needed for a number pool or an alphanumeric sender id. With one set, the number above may be left blank":"केवल नंबर पूल या अल्फ़ान्यूमेरिक सेंडर आईडी के लिए ज़रूरी है। एक सेट होने पर ऊपर का नंबर खाली छोड़ा जा सकता है",
"Only needed if your invoices charge tax":"केवल तब ज़रूरी जब आपके चालानों में कर लगता हो",
"Only numbers that have texted the line can be answered here":"यहाँ केवल उन्हीं नंबरों को जवाब दिया जा सकता है जिन्होंने लाइन पर टेक्स्ट किया है",
"Only pending instalments can be deleted. Void an issued one from Accounting":"केवल लंबित किस्तें हटाई जा सकती हैं। जारी की गई किस्त को लेखा से रद्द करें",
"Only people who agreed to texts receive any of these, and each person can turn kinds off in their own profile. Consent confirmations and STOP replies always go. Saved with":"इनमें से कुछ भी केवल उन्हीं लोगों को मिलता है जिन्होंने टेक्स्ट के लिए सहमति दी है, और हर व्यक्ति अपनी प्रोफ़ाइल में प्रकार बंद कर सकता है। सहमति की पुष्टि और STOP के जवाब हमेशा जाते हैं। इसके साथ सहेजा जाता है",
"Only people who have agreed can be sent a text. Emailing the link below asks them in one tap":"केवल वही लोग टेक्स्ट पा सकते हैं जिन्होंने सहमति दी है। नीचे दिया लिंक ईमेल करने पर वे एक टैप में सहमति दे सकते हैं",
"Only people who have agreed can be sent a text. Emailing the link below asks them in one tap — no sign-in needed — and records their answer with the exact wording they were shown":"केवल वही लोग टेक्स्ट पा सकते हैं जिन्होंने सहमति दी है। नीचे दिया लिंक ईमेल करने पर वे एक टैप में सहमति दे सकते हैं — साइन इन की ज़रूरत नहीं — और उनका उत्तर उन्हें दिखाए गए सटीक शब्दों के साथ दर्ज होता है",
"Only people who have not tapped ✓ Done":"केवल वे लोग जिन्होंने ✓ हो गया नहीं दबाया",
"Only people who haven’t tapped":"केवल वे लोग जिन्होंने नहीं दबाया",
"Only recipients who opted in to SMS and have a phone number on file will receive it":"इसे केवल वे प्राप्तकर्ता पाएँगे जिन्होंने SMS के लिए सहमति दी है और जिनका फ़ोन नंबर दर्ज है",
