"Only this person can change these details. They are stored encrypted and this screen shows the last few digits":"केवल यही व्यक्ति ये विवरण बदल सकता है। ये एन्क्रिप्ट करके रखे जाते हैं और यह स्क्रीन केवल आखिरी कुछ अंक दिखाती है",
"Only this person can change these details. They are stored encrypted and this screen shows the last few digits — enough to confirm the right account is on file, and useless to anyone reading over a shoulder":"केवल यही व्यक्ति ये विवरण बदल सकता है। ये एन्क्रिप्ट करके रखे जाते हैं और यह स्क्रीन केवल आखिरी कुछ अंक दिखाती है — यह पुष्टि करने के लिए काफ़ी है कि सही खाता दर्ज है, और कंधे के ऊपर से झाँकने वाले किसी के लिए बेकार",
