"Opens are counted when the email’s images load, so people who block images open without being counted. Clicks and responses are exact":"ओपन तब गिने जाते हैं जब ईमेल की छवियाँ लोड होती हैं, इसलिए जो लोग छवियाँ ब्लॉक करते हैं वे बिना गिने खोलते हैं। क्लिक और जवाब सटीक हैं",
"Opens are seen when the prospect’s mail app shows images. Some block images (no open is reported) and Apple Mail can report an open on its own; CC/BCC copies count too":"ओपन तब दिखते हैं जब प्रॉस्पेक्ट का मेल ऐप इमेज दिखाता है। कुछ इमेज ब्लॉक करते हैं (कोई ओपन रिपोर्ट नहीं होता) और Apple Mail अपने आप भी ओपन रिपोर्ट कर सकता है; CC/BCC प्रतियाँ भी गिनी जाती हैं",
"Opens instantly, even after you swipe it away. Shows a small notification. Uses very little battery":"तुरंत खुलता है, स्वाइप करके हटाने के बाद भी। एक छोटी सूचना दिखाता है। बहुत कम बैटरी इस्तेमाल करता है",
