"That's the whirlwind tour! Start by adding your centres and rooms, then invite your families. Everything you saw is one click away in the sidebar — and Help is always there if you get stuck":"यह था फटाफट टूर! अपने केंद्र और कक्ष जोड़कर शुरू करें, फिर अपने परिवारों को आमंत्रित करें। आपने जो कुछ देखा वह साइडबार में एक क्लिक की दूरी पर है — और अटकने पर मदद हमेशा मौजूद है",
"The":"वह",
"The App Store is opening - tap Update there":"App Store खुल रहा है - वहाँ अपडेट पर टैप करें",
"The Claude (AI) connection, its estimated credits and every AI call KiddieTrac makes - by agency, feature and model":"Claude (AI) कनेक्शन, उसके अनुमानित क्रेडिट और KiddieTrac द्वारा किया गया हर AI कॉल - एजेंसी, सुविधा और मॉडल के अनुसार",
"The Daily log captures attendance and day events. Turn on One-Tap (QR contactless check-in) and kiosk check-in per centre so families sign in/out from a poster at the door":"दैनिक लॉग उपस्थिति और दिन की घटनाएँ दर्ज करता है। परिवार दरवाज़े पर लगे पोस्टर से साइन इन/आउट कर सकें, इसके लिए हर केंद्र पर One-Tap (QR कोड से संपर्क-रहित चेक-इन) और कियोस्क चेक-इन चालू करें",
"The Dashboard shows MRR, ARR, active centres, and platform-wide stats":"डैशबोर्ड में MRR, ARR, सक्रिय केंद्र और पूरे प्लेटफ़ॉर्म के आँकड़े दिखते हैं",
"The Google client that lets an agency connect a Gmail account under":"वह Google क्लाइंट जो किसी एजेंसी को Gmail खाता जोड़ने देता है",
"The KiddieTrac Android app watches the educator’s location in the background so a walk is noticed even with the phone in a pocket. Android asks each educator to allow location “all the time” and shows a":"KiddieTrac Android ऐप पृष्ठभूमि में शिक्षक की लोकेशन देखता है ताकि फ़ोन जेब में होने पर भी सैर का पता चल जाए। Android हर शिक्षक से लोकेशन “हर समय” की अनुमति माँगता है और एक",
"The KiddieTrac team has it":"KiddieTrac टीम को मिल गया है",
"The Microsoft app people sign in through when they connect a mailbox in":"वह Microsoft ऐप जिससे लोग साइन इन करते हैं जब वे मेलबॉक्स जोड़ते हैं",
"The PDF certificate":"PDF प्रमाणपत्र",
"The PDF is attached to a thank-you email from your agency":"PDF आपकी एजेंसी के धन्यवाद ईमेल के साथ संलग्न होती है",
"The PDF is attached. Separate several addresses with commas. A draft becomes issued once it is sent":"PDF संलग्न है। कई पते अल्पविराम से अलग करें। ड्राफ़्ट भेजे जाने पर जारी हो जाता है",
"The Pipeline's weighted forecast multiplies each lead's estimated annual revenue by its stage's chance":"पाइपलाइन का भारित पूर्वानुमान हर संभावित ग्राहक के अनुमानित वार्षिक राजस्व को उसके चरण की संभावना से गुणा करता है",
"The RSVP form people see from the invitation or the shareable link":"आमंत्रण या साझा करने योग्य लिंक से लोगों को दिखने वाला RSVP फ़ॉर्म",
"The RSVP link stops taking sign-ups. Everything already received stays in the report, and you can reopen it later":"RSVP लिंक साइन-अप लेना बंद कर देता है। अब तक मिला सब कुछ रिपोर्ट में रहता है, और आप इसे बाद में फिर से खोल सकते हैं",
"The Teams link stays the same":"Teams लिंक वही रहता है",
"The Today screen shows your child's sign-in time, room, mood, and updates from staff":"आज की स्क्रीन आपके बच्चे के साइन-इन का समय, कक्ष, मूड और स्टाफ़ के अपडेट दिखाती है",
"The Today tab shows sign-ins, ratios, late pickups, and your current room status at a glance":"आज टैब साइन-इन, अनुपात, देर से लेने आना और आपके कक्ष की मौजूदा स्थिति एक नज़र में दिखाता है",
"The Twilio number in full international form, or a Messaging Service SID (MG":"पूर्ण अंतरराष्ट्रीय प्रारूप में Twilio नंबर, या Messaging Service SID (MG",
"The Website control center is restricted to platform super-admins":"वेबसाइट कंट्रोल सेंटर केवल प्लेटफ़ॉर्म सुपर-एडमिन के लिए सीमित है",
