"The agency carries your brand. Its admin is emailed an invite to set a password, and you can manage it straight away from All my agencies":"एजेंसी आपका ब्रांड दिखाती है। उसके एडमिन को पासवर्ड सेट करने का आमंत्रण ईमेल किया जाता है, और आप उसे तुरंत मेरी सभी एजेंसियाँ से प्रबंधित कर सकते हैं",
"The agency is emailed a refund receipt. Send the money back yourself (card terminal, e-Transfer or cheque); this records it":"एजेंसी को धनवापसी की रसीद ईमेल की जाती है। पैसा आप स्वयं वापस भेजें (कार्ड टर्मिनल, e-Transfer या चेक); यह उसे दर्ज करता है",
"The agency master switch above is":"ऊपर एजेंसी का मास्टर स्विच",
"The agency’s contact book":"एजेंसी की संपर्क पुस्तिका",
"The agency’s contact book — suppliers, trades, inspectors, insurers. Everyone the business deals with — plus the staff and families already on the system — in one place instead of one person’s phone":"एजेंसी की संपर्क पुस्तिका — आपूर्तिकर्ता, कारीगर, निरीक्षक, बीमाकर्ता। व्यवसाय जिन-जिन से व्यवहार करता है — साथ ही सिस्टम में पहले से मौजूद कर्मचारी और परिवार — किसी एक व्यक्ति के फ़ोन की जगह एक ही स्थान पर",
"The attached contract":"संलग्न अनुबंध",
