"The centre has to authorise a medication before an educator can give it. Fill this in and they will be notified":"केंद्र को दवा अधिकृत करनी होगी, तभी शिक्षक उसे दे सकता है। इसे भरें और उन्हें सूचित कर दिया जाएगा",
"The centre is already closed for these dates, so nothing more is needed":"इन तारीखों पर केंद्र पहले से बंद है, इसलिए और कुछ आवश्यक नहीं",
