"The colour band at the top of every page. Leave a colour blank to use your primary → accent colours":"हर पेज के ऊपर की रंग पट्टी। अपने प्राथमिक → एक्सेंट रंगों का उपयोग करने के लिए कोई रंग खाली छोड़ें",
"The connection was lost":"कनेक्शन टूट गया",
"The contact is removed from the book. It is kept in the record rather than destroyed, so it can be restored if this was a mistake":"संपर्क पुस्तिका से हटा दिया जाता है। उसे नष्ट करने की बजाय रिकॉर्ड में रखा जाता है, इसलिए गलती होने पर उसे बहाल किया जा सकता है",
"The contract must be under 15 MB":"अनुबंध 15 MB से कम होना चाहिए",
"The copy keeps the questions, email and image. Its sign-up address is left blank for that agency to set":"कॉपी में प्रश्न, ईमेल और छवि रहते हैं। उसका साइन-अप पता उस एजेंसी के सेट करने के लिए खाली छोड़ा जाता है",
"The counter-signature is recorded, but the PDF could not be stamped. The original form is unchanged":"प्रतिहस्ताक्षर दर्ज है, पर PDF पर मुहर नहीं लग सकी। मूल फ़ॉर्म अपरिवर्तित है",
"The current connection belongs to the old app or environment, so QuickBooks will be disconnected and you will connect again":"वर्तमान कनेक्शन पुराने ऐप या परिवेश का है, इसलिए QuickBooks डिस्कनेक्ट हो जाएगा और आपको फिर से कनेक्ट करना होगा",
