"The daily and weekly summary emails to admins and directors, and the daily summaries to parents and educators. Everything else (invitations, reminders, notices) follows the switch above":"एडमिन और निदेशकों को दैनिक और साप्ताहिक सारांश ईमेल, और अभिभावकों व शिक्षकों को दैनिक सारांश। बाकी सब (आमंत्रण, रिमाइंडर, सूचनाएं) ऊपर वाले स्विच के अनुसार चलता है",
"The date and the amount are needed":"तारीख और राशि आवश्यक हैं",
"The date range on the screen":"स्क्रीन पर दी गई तारीख़ सीमा",
