"The framework you plan and report against: HDLH, ELECT, BC ELF, Flight, EYFS and more":"वह ढाँचा जिसके आधार पर आप योजना बनाते और रिपोर्ट करते हैं: HDLH, ELECT, BC ELF, Flight, EYFS और अन्य",
"The framework your agency plans and reports against. It sets the areas observations link to, the sections of report cards, and the gaps report":"वह ढाँचा जिसके आधार पर आपकी एजेंसी योजना बनाती और रिपोर्ट करती है। यह तय करता है कि अवलोकन किन क्षेत्रों से जुड़ते हैं, रिपोर्ट कार्ड के अनुभाग क्या होंगे, और गैप रिपोर्ट",
