"The hand-checked dictionary shipped with the site is not listed here — only text translated automatically since. Keep any":"साइट के साथ आने वाली हाथ से जाँची गई शब्दावली यहाँ सूचीबद्ध नहीं है — केवल उसके बाद स्वचालित रूप से अनुवादित टेक्स्ट है। इन्हें बनाए रखें",
"The hours go with it. The removal is written to the audit log with your name and the times it held, which is the only record of it afterwards":"घंटे उसके साथ चले जाते हैं। हटाने की प्रविष्टि आपके नाम और उसमें दर्ज समय के साथ ऑडिट लॉग में लिखी जाती है, जो बाद में इसका एकमात्र रिकॉर्ड रहता है",
"The icon is the Brand tab’s square logo; the boot screen uses its colours":"आइकन ब्रांड टैब का चौकोर लोगो है; बूट स्क्रीन उसके रंग इस्तेमाल करती है",
