"The invoice line description. Filled in with the child and their care when you pick the family — change it as you like. Optional placeholders, filled on each invoice":"चालान की लाइन का विवरण। परिवार चुनते ही बच्चे और उसकी देखभाल के साथ भर जाता है — जैसा चाहें बदलें। वैकल्पिक प्लेसहोल्डर, हर चालान पर भरे जाते हैं",
