"The people on your family’s file at the centre. You can ask the centre to give an emergency contact their own pick-up login, so they can check the children in and out with One-Tap from their own phone. They never see billing":"केंद्र में आपके परिवार की फ़ाइल में मौजूद लोग। आप केंद्र से कह सकते हैं कि किसी आपातकालीन संपर्क को अपना पिक-अप लॉगिन दे, ताकि वे अपने फ़ोन से One-Tap द्वारा बच्चों को चेक इन और चेक आउट कर सकें। वे बिलिंग कभी नहीं देखते",
