"The picture at the top of the message. Uploads are kept — pick one you have used before, or add a new one":"संदेश के शीर्ष पर दिखने वाली तस्वीर। अपलोड सहेजे जाते हैं — पहले उपयोग की हुई कोई चुनें, या नई जोड़ें",
"The plan and every add-on are cancelled and their features switch off straight away. They stay listed as cancelled":"योजना और सभी ऐड-ऑन रद्द हो जाते हैं और उनकी सुविधाएँ तुरंत बंद हो जाती हैं। वे रद्द के रूप में सूचीबद्ध रहते हैं",
