"The schedule says what a child of that age owes; the record says what this centre has actually typed up. Where nothing has been typed up, the family is asked for the record instead":"कैलेंडर बताता है कि उस उम्र के बच्चे को क्या मिलना चाहिए; रिकॉर्ड बताता है कि इस केंद्र ने वास्तव में क्या दर्ज किया है। जहाँ कुछ दर्ज नहीं है, वहाँ परिवार से रिकॉर्ड माँगा जाता है",
"The schedule says what a child of that age owes; the record says what this centre has actually typed up. Where nothing has been typed up, the family is asked for the record instead — and if their card is already on file, they are not written to at all, because that one is ours to transcribe":"कैलेंडर बताता है कि उस उम्र के बच्चे को क्या मिलना चाहिए; रिकॉर्ड बताता है कि इस केंद्र ने वास्तव में क्या दर्ज किया है। जहाँ कुछ दर्ज नहीं है, वहाँ परिवार से रिकॉर्ड माँगा जाता है — और यदि उनका कार्ड पहले से फ़ाइल में है, तो उन्हें बिल्कुल नहीं लिखा जाता, क्योंकि उसे दर्ज करना हमारा काम है",
