"The test rings only the number above, or your own profile number when that is blank. It works while voice calls are off, so you can try it before switching them on":"टेस्ट केवल ऊपर का नंबर बजाता है, या वह खाली होने पर आपकी प्रोफ़ाइल का नंबर। यह वॉइस कॉल बंद होने पर भी काम करता है, ताकि आप उन्हें चालू करने से पहले आज़मा सकें",
"The test rings the mobile number on your own profile, uses \"Test Child\", and records nothing. The voice is set in Carrier settings → Voice calls":"टेस्ट आपकी अपनी प्रोफ़ाइल के मोबाइल नंबर पर रिंग करता है, “Test Child” का उपयोग करता है और कुछ भी रिकॉर्ड नहीं करता। आवाज़ कैरियर सेटिंग्स → वॉइस कॉल में सेट होती है",
