"The welcome email was blocked before it was delivered":"स्वागत ईमेल डिलीवर होने से पहले ही अवरुद्ध हो गया",
"The white-label licence (chargeable":"व्हाइट-लेबल लाइसेंस (शुल्कयोग्य",
"The white-label licence (chargeable — include it in the monthly amount on Plan; suggest +$50/mo). When enabled, the agency’s logo replaces KiddieTrac in the portal top bar for every role, the app’s loading and unlock screens, the sign-in page of their branded app, and on emails, invoices and forms; the \"Powered by Kiddietrac\" footer is hidden; and marketing campaigns can be sent from the agency’s own mailbox (a Gmail / Google Workspace sender account). The rest of their branding (invoices, email delivery, payslips) is under Reseller › Branding while switched into the agency":"व्हाइट-लेबल लाइसेंस (शुल्कयोग्य — इसे योजना की मासिक राशि में शामिल करें; सुझाव +$50/माह)। चालू होने पर, एजेंसी का लोगो हर भूमिका के लिए पोर्टल के शीर्ष बार में, ऐप की लोडिंग और अनलॉक स्क्रीन में, उनके ब्रांडेड ऐप के साइन-इन पृष्ठ में, और ईमेल, चालानों व फ़ॉर्म पर KiddieTrac की जगह लेता है; “Powered by Kiddietrac” फ़ुटर छिपा दिया जाता है; और मार्केटिंग अभियान एजेंसी के अपने मेलबॉक्स (Gmail / Google Workspace प्रेषक खाता) से भेजे जा सकते हैं। उनकी बाकी ब्रांडिंग (चालान, ईमेल वितरण, पे-स्लिप) एजेंसी में स्विच करने पर रीसेलर › ब्रांडिंग के अंतर्गत है",
"The whole agency":"पूरी एजेंसी",
"The wording of every email KiddieTrac sends for you":"हर उस ईमेल का पाठ जो KiddieTrac आपकी ओर से भेजता है",
"The writing helper is busy, so this is our standard letter. Edit anything before sending":"लेखन सहायक व्यस्त है, इसलिए यह हमारा मानक पत्र है। भेजने से पहले कुछ भी संपादित करें",
"The written record of contraventions of your policies and the action taken (O. Reg. 137/15 s.6.1). Kept on file":"आपकी नीतियों के उल्लंघनों और की गई कार्रवाई का लिखित रिकॉर्ड (O. Reg. 137/15 s.6.1)। रिकॉर्ड में रखा जाता है",
"The 👋 beside the ＋ in every chat rings the other person's phone, shakes their screen and plays the nudge sound. Each person picks their nudge sound in Settings › Notifications › Sounds & vibration":"हर चैट में ＋ के बगल का 👋 दूसरे व्यक्ति का फ़ोन बजाता है, उनकी स्क्रीन हिलाता है और नज ध्वनि बजाता है। हर व्यक्ति अपनी नज ध्वनि सेटिंग्स › सूचनाएँ › ध्वनियाँ और कंपन में चुनता है",
"The 📞 beside the 👋 in every chat starts a voice call inside KiddieTrac. No phone numbers are shared, and calls are not recorded. It rings on computers and Android phones; on an iPhone with the app closed it arrives as a notification to tap":"हर चैट में 👋 के बगल का 📞 KiddieTrac के अंदर वॉइस कॉल शुरू करता है। कोई फ़ोन नंबर साझा नहीं किया जाता और कॉल रिकॉर्ड नहीं की जातीं। यह कंप्यूटर और Android फ़ोन पर बजता है; ऐप बंद होने पर iPhone पर यह टैप करने योग्य सूचना के रूप में आता है",
