"Their last day, what happens to their records, and any hours not yet on a payslip. Sent before access ends":"उनका अंतिम दिन, उनके रिकॉर्ड का क्या होगा, और वे घंटे जो अभी पेस्लिप में नहीं हैं। पहुँच समाप्त होने से पहले भेजा जाता है",
"Their link stops working. You can send a new one later":"उनका लिंक काम करना बंद कर देता है। आप बाद में नया भेज सकते हैं",
