"Their login is removed. Forms they already signed stay on record. Do this only if they are not joining — adding their family links them instead":"उनका लॉग इन हटा दिया जाता है। जो फ़ॉर्म वे पहले ही साइन कर चुके हैं वे रिकॉर्ड में रहते हैं। ऐसा केवल तभी करें जब वे जुड़ने वाले न हों — उनका परिवार जोड़ने से वे इसके बजाय जुड़ जाते हैं",
"Their messages are hidden from you":"उनके संदेश आपसे छिपा दिए गए हैं",
"Their messages are hidden from you, and they no longer notify you":"उनके संदेश आपसे छिपा दिए जाते हैं और अब आपको सूचित नहीं करते",
"Their name":"उनका नाम",
"Their own app":"उनका अपना ऐप",
"Their phone will ring and vibrate continuously until they open it (up to 2 minutes). Use this only for real emergencies":"उनका फ़ोन तब तक लगातार बजेगा और कंपन करेगा जब तक वे उसे खोल नहीं लेते (अधिकतम 2 मिनट)। इसे केवल असली आपात स्थितियों के लिए उपयोग करें",
"Their phone will ring and vibrate continuously until they open it (up to 2 minutes). Use this only for real emergencies — everyone who receives it is told it is urgent":"उनका फ़ोन तब तक लगातार बजेगा और कंपन करेगा जब तक वे उसे खोल नहीं लेते (अधिकतम 2 मिनट)। इसे केवल असली आपात स्थितियों के लिए उपयोग करें — इसे पाने वाले हर व्यक्ति को बताया जाता है कि यह अत्यावश्यक है",
"Their pick-up login will stop working too":"उनका पिक-अप लॉगिन भी काम करना बंद कर देगा",
"Their provider now":"उनका वर्तमान प्रदाता",
"Their sign-in ends immediately and their rooms are released. The record is kept":"उनका साइन-इन तुरंत समाप्त हो जाता है और उनके कक्ष मुक्त कर दिए जाते हैं। रिकॉर्ड रखा जाता है",
"Their sign-in ends immediately and their rooms are released. The record is kept — you will find them under Show deactivated":"उनका साइन-इन तुरंत समाप्त हो जाता है और उनके कक्ष मुक्त कर दिए जाते हैं। रिकॉर्ड रखा जाता है — वह आपको निष्क्रिय दिखाएँ के अंतर्गत मिलेगा",
"Their tax registration no":"उनका कर पंजीकरण नंबर",
