"This removes it entirely. Only a draft that was never emailed can be deleted — anything a customer has seen must be voided instead, so the record of it survives":"यह इसे पूरी तरह हटा देता है। केवल वही ड्राफ़्ट हटाया जा सकता है जो कभी ईमेल नहीं किया गया — जो कुछ भी ग्राहक ने देखा है उसे इसके बजाय रद्द करना होगा, ताकि उसका रिकॉर्ड बना रहे",
