"This ticket is with the platform team":"यह टिकट प्लेटफ़ॉर्म टीम के पास है",
"This version of the KiddieTrac app cannot use the microphone for calls. Update the app (3.12.5 or later), then call again":"KiddieTrac ऐप का यह संस्करण कॉल के लिए माइक्रोफ़ोन का उपयोग नहीं कर सकता। ऐप अपडेट करें (3.12.5 या बाद का), फिर दोबारा कॉल करें",
