"Tick at least two guardians":"कम से कम दो अभिभावक चुनें",
"Tick each day that should include":"हर उस दिन पर निशान लगाएँ जिसमें शामिल होना चाहिए",
"Tick each dose the record shows. A date is optional":"रिकॉर्ड में दिखने वाली हर खुराक पर टिक करें। तारीख वैकल्पिक है",
"Tick each dose the record shows. A date is optional — leave it blank if the card is unclear, the dose still counts as recorded. Anything the card shows that is not on the list can be added underneath":"रिकॉर्ड में दिखने वाली हर खुराक पर टिक करें। तारीख वैकल्पिक है — कार्ड साफ़ न हो तो उसे खाली छोड़ दें, खुराक फिर भी दर्ज मानी जाएगी। कार्ड पर जो कुछ सूची में नहीं है, उसे नीचे जोड़ा जा सकता है",
"Tick each immunization you can see on the record. This helps the centre read it":"रिकॉर्ड पर दिखने वाले हर टीकाकरण पर टिक करें। इससे केंद्र को इसे पढ़ने में मदद मिलती है",
"Tick each immunization you can see on the record. This helps the centre read it — they will confirm each one before it counts. A date is optional; leave it blank if the card is unclear":"रिकॉर्ड पर दिखने वाले हर टीकाकरण पर टिक करें। इससे केंद्र को इसे पढ़ने में मदद मिलती है — गिने जाने से पहले वे हर एक की पुष्टि करेंगे। तारीख वैकल्पिक है; कार्ड साफ़ न हो तो उसे खाली छोड़ दें",
"Tick the box to confirm you control that number":"यह पुष्टि करने के लिए बॉक्स पर निशान लगाएँ कि वह नंबर आपके नियंत्रण में है",
"Tick the box to confirm you have read and understand it":"पुष्टि करने के लिए बॉक्स चुनें कि आपने इसे पढ़ा और समझा है",
"Tick the box to confirm you reviewed every account":"पुष्टि करने के लिए बॉक्स पर टिक करें कि आपने सभी खातों की समीक्षा की है",
"Tick the prospects to email first, or use “Select all” in the batch":"पहले जिन प्रॉस्पेक्ट को ईमेल करना है उन पर टिक करें, या बैच में “सभी चुनें” का उपयोग करें",
