"What you owe after any subsidy is applied to the full tuition. Pay this amount to your centre directly (e-transfer, cheque, etc":"पूरे ट्यूशन पर कोई भी सब्सिडी लगने के बाद आप पर बकाया राशि। यह राशि सीधे अपने केंद्र को चुकाएँ (ई-ट्रांसफ़र, चेक आदि",
