"Which rooms a person works in. This decides whose children they see, and lets attendance and sign-out figures be attributed to a person rather than a whole centre. Anyone can be assigned to any room":"कोई व्यक्ति किन कक्षों में काम करता है। इससे तय होता है कि वह किन बच्चों को देखता है, और उपस्थिति तथा साइन-आउट के आँकड़े पूरे केंद्र के बजाय किसी व्यक्ति से जोड़े जा सकते हैं। किसी को भी किसी भी कक्ष में असाइन किया जा सकता है",
"Which rooms a person works in. This decides whose children they see, and lets attendance and sign-out figures be attributed to a person rather than a whole centre. Anyone can be assigned to any room — their own centre is marked":"कोई व्यक्ति किन कक्षों में काम करता है। इससे तय होता है कि वह किन बच्चों को देखता है, और उपस्थिति तथा साइन-आउट के आँकड़े पूरे केंद्र के बजाय किसी व्यक्ति से जोड़े जा सकते हैं। किसी को भी किसी भी कक्ष में असाइन किया जा सकता है — उनका अपना केंद्र चिह्नित होता है",
