"While a subsidy applies, its monthly amount comes off that child's tuition on the family's invoice. One subsidy per child at a time":"जब तक सब्सिडी लागू है, उसकी मासिक राशि परिवार के चालान में बच्चे की ट्यूशन से घटाई जाती है। एक समय में प्रति बच्चा एक ही सब्सिडी",
"While it applies, the subsidy comes off the child's tuition on each monthly invoice (never more than the tuition). Invoices already issued are not changed":"जब तक यह लागू है, सब्सिडी हर मासिक चालान में बच्चे की ट्यूशन से घटाई जाती है (ट्यूशन से अधिक कभी नहीं)। पहले जारी चालान नहीं बदलते",
