"You can still pay your invoices by e-transfer or the method your centre uses":"आप फिर भी अपने चालान ई-ट्रांसफ़र या अपने केंद्र द्वारा उपयोग की जाने वाली विधि से चुका सकते हैं",
"You can unblock them any time from ⋯ on one of their messages":"आप उनके किसी संदेश पर ⋯ से कभी भी अनब्लॉक कर सकते हैं",
