"You can update their name, phone, address and profile. Their sign-in email, username, roles and account status are changed by an agency admin":"आप उनका नाम, फ़ोन, पता और प्रोफ़ाइल अपडेट कर सकते हैं। उनका साइन-इन ईमेल, उपयोगकर्ता नाम, भूमिकाएँ और खाते की स्थिति एजेंसी एडमिन बदलते हैं",
"You can use {{first_name}}, {{name}}, {{event}}, {{date}}, {{location}} and {{agency}}. The RSVP button, the event details and an unsubscribe link are added for you":"आप {{first_name}}, {{name}}, {{event}}, {{date}}, {{location}} और {{agency}} का उपयोग कर सकते हैं। RSVP बटन, कार्यक्रम का विवरण और सदस्यता रद्द करने का लिंक आपके लिए जोड़ दिया जाता है",
"You cannot clock out yet":"आप अभी क्लॉक आउट नहीं कर सकते",
"You checked every child's days and the capacity. A different person then signs it off":"आपने हर बच्चे के दिन और क्षमता की जाँच कर ली है। फिर कोई और व्यक्ति इस पर हस्ताक्षर करता है",
"You counted them here, so Safe Arrival won't message the parents. Sign them in on your roster so attendance and ratios are right":"आपने उन्हें यहाँ गिना है, इसलिए Safe Arrival अभिभावकों को संदेश नहीं भेजेगा। उपस्थिति और अनुपात सही रहें, इसके लिए उन्हें अपने रोस्टर में साइन इन करें",
