"Your answer":"आपका उत्तर",
"Your answers are kept until you sign":"आपके उत्तर आपके हस्ताक्षर करने तक सुरक्षित रहते हैं",
"Your bank account is on file":"आपका बैंक खाता दर्ज है",
"Your billing history will build up here month by month":"आपका बिलिंग इतिहास यहाँ महीने दर महीने बनता जाएगा",
"Your bio":"आपका परिचय",
"Your bio is a little short":"आपका परिचय थोड़ा छोटा है",
"Your bio is a little short — add a sentence or two more (at least 40 characters":"आपका परिचय थोड़ा छोटा है — एक-दो वाक्य और जोड़ें (कम से कम 40 अक्षर",
"Your bio is the first thing a new family reads: it goes in their welcome email and on your provider card. Right now they see a placeholder. It takes about 2 minutes":"आपका परिचय नया परिवार सबसे पहले पढ़ता है: यह उनके स्वागत ईमेल और आपके प्रदाता कार्ड में दिखता है। अभी उन्हें एक अस्थायी टेक्स्ट दिखता है। इसमें लगभग 2 मिनट लगते हैं",
"Your browser blocked the microphone. Tap the lock or settings icon beside the address, allow":"आपके ब्राउज़र ने माइक्रोफ़ोन को ब्लॉक कर दिया है। पते के पास ताले या सेटिंग्स के आइकन पर टैप करें, अनुमति दें",
"Your browser blocked the pop-up":"आपके ब्राउज़र ने पॉप-अप ब्लॉक कर दिया",
"Your browser blocked the pop-up — allow pop-ups for this site":"आपके ब्राउज़र ने पॉप-अप ब्लॉक कर दिया — इस साइट के लिए पॉप-अप की अनुमति दें",
"Your browser blocked the pop-up — allow pop-ups for this site, or use Download":"आपके ब्राउज़र ने पॉप-अप ब्लॉक कर दिया — इस साइट के लिए पॉप-अप की अनुमति दें, या डाउनलोड का उपयोग करें",
"Your browser did not allow copying automatically":"आपके ब्राउज़र ने अपने आप कॉपी करने की अनुमति नहीं दी",
"Your browser did not allow copying automatically — select the link and copy it":"आपके ब्राउज़र ने अपने आप कॉपी करने की अनुमति नहीं दी — लिंक चुनकर कॉपी करें",
"Your browser is blocking notifications from KiddieTrac. Tap to see how to turn them back on":"आपका ब्राउज़र KiddieTrac के नोटिफ़िकेशन रोक रहा है। उन्हें फिर चालू करने का तरीका देखने के लिए टैप करें",
"Your browser rings first and connects by itself; then the person you are calling rings. Keep this tab open during the call":"आपका ब्राउज़र पहले बजता है और अपने आप कनेक्ट हो जाता है; फिर जिसे आप कॉल कर रहे हैं उसका फ़ोन बजता है। कॉल के दौरान इस टैब को खुला रखें",
