"Your card is saved securely with Stripe. You can turn this off any time":"आपका कार्ड Stripe के साथ सुरक्षित रूप से सहेजा जाता है। आप इसे कभी भी बंद कर सकते हैं",
"Your centre and KiddieTrac will be notified":"आपके केंद्र और KiddieTrac को सूचित किया जाएगा",
"Your centre has been notified. You have not been onboarded":"आपके केंद्र को सूचित कर दिया गया है। आपको शामिल नहीं किया गया है",
"Your centre this month":"इस महीने आपका केंद्र",
"Your centre will be told and will contact you":"आपके केंद्र को सूचित किया जाएगा और वे आपसे संपर्क करेंगे",
"Your centre will be told straight away, and we'll stop reminding you to sign in today":"आपके केंद्र को तुरंत सूचित कर दिया जाएगा, और हम आज आपको साइन इन करने की याद दिलाना बंद कर देंगे",
"Your centre will reach out about your child's day":"आपका केंद्र आपके बच्चे के दिन के बारे में आपसे संपर्क करेगा",
"Your child has been checked out for the day, or hasn't arrived yet":"आपके बच्चे को आज के लिए चेक-आउट कर दिया गया है, या वह अभी पहुँचा नहीं है",
"Your child is currently checked in at the daycare. The educator marked their arrival":"आपका बच्चा इस समय डेकेयर में चेक-इन है। शिक्षक ने उसका आगमन दर्ज किया है",
"Your child's day at a glance":"आपके बच्चे का दिन एक नज़र में",
"Your childcare centre will link your account to your child once enrolled. Check back soon":"नामांकन होने के बाद आपका चाइल्डकेयर केंद्र आपके अकाउंट को आपके बच्चे से जोड़ देगा। जल्द ही फिर देखें",
