"above — it reads the carrier's account rather than sending anything, so it costs nothing and needs no consenting recipient":"ऊपर — यह कुछ भेजे बिना कैरियर का खाता पढ़ता है, इसलिए इसमें कोई खर्च नहीं और किसी सहमति देने वाले प्राप्तकर्ता की ज़रूरत नहीं",
